mapper.insert:
insert into sale_order (
    order_no, student_name, phone, product_id, class_id, student_code, product_amount, discount_amount,
    receivable_amount, paid_amount, order_status, created_at, updated_at
) values (
    #{orderNo}, #{studentName}, #{phone}, #{productId}, #{classId}, #{studentCode}, #{productAmount}, #{discountAmount},
    #{receivableAmount}, #{paidAmount}, #{orderStatus}, #{createdAt}, #{updatedAt}
)

mapper.select:
select from sale_order o left join sale_product p on p.id = o.product_id left join edu_class c on c.id = o.class_id left join edu_student s on s.student_code = o.student_code and s.product_id = o.product_id and s.phone = o.phone and (p.study_mode = 'ONLINE' or s.class_id = o.class_id)
and ( o.order_no like concat('%', #{keyword}, '%') or o.student_name like concat('%', #{keyword}, '%') or o.phone like concat('%', #{keyword}, '%') or o.student_code like concat('%', #{keyword}, '%') or ifnull(p.product_name, '') like concat('%', #{keyword}, '%') )
and o.order_status = #{orderStatus}
and () = #{fulfillmentStatus}
order by o.id desc
